class DiagnoseFromSymptomsModule(dspy.Module):
    def __init__(self):
        super().__init__()
        self.predict = dspy.Predict(dspy.Signature("symptoms: str -> disease: Literal['allergy', 'arthritis', 'bronchial asthma', 'cervical spondylosis', 'chicken pox', 'common cold', 'dengue', 'diabetes', 'drug reaction', 'fungal infection', 'gastroesophageal reflux disease', 'hypertension', 'impetigo', 'jaundice', 'malaria', 'migraine', 'peptic ulcer disease', 'pneumonia', 'psoriasis', 'typhoid', 'urinary tract infection', 'varicose veins']", "Given a patient's description of their symptoms, name the disease."))

    def forward(self, **inputs):
        result = self.predict(**inputs)
        return dspy.Prediction(disease=result.disease)
